export default function prepare({ values }) {
  const h = values?.[0];
  if (
    !Array.isArray(h) ||
    h.length !== 4 ||
    new Set(h).size !== 4 ||
    !["ID", "Name", "Rent", "City"].every((x) => h.includes(x))
  )
    throw Error("First row must have unique ID, Name, Rent, City headers in A:D");
  const id = Math.floor(Math.random() * 1000),
    data = { ID: id, Name: "John's Place", Rent: 1000, City: "Berlin" };
  return { values: [h.map((k) => data[k])] };
}

