export default function plan({ values }) {
  const h = values?.[0];
  if (
    !Array.isArray(h) ||
    h.length !== 4 ||
    new Set(h).size !== 4 ||
    !["ID", "Name", "Rent", "City"].every((x) => h.includes(x))
  )
    throw Error("First row must have unique ID, Name, Rent, City headers in A:D");
  const ids = new Map(),
    items = [];
  for (let i = 1; i < values.length; i++) {
    const r = values[i];
    if (!Array.isArray(r) || !r.length) continue;
    const id = r[h.indexOf("ID")];
    if (id === undefined || id === null || id === "") throw Error("Each row must have an ID");
    const k = String(id);
    ids.set(k, (ids.get(k) || 0) + 1);
    if (r[h.indexOf("City")] === "Berlin") {
      const rent = r[h.indexOf("Rent")];
      if (typeof rent !== "number" || !Number.isFinite(rent))
        throw Error("Berlin rent must be numeric");
      items.push({
        id,
        range: String.fromCharCode(65 + h.indexOf("Rent")) + (i + 1),
        values: [[rent + 100]],
      });
    }
  }
  for (const item of items)
    if (ids.get(String(item.id)) !== 1) throw Error("Matching row ID is not unique");
  return {
    more: items.length > 0,
    data: items.length
      ? items.map(({ range, values }) => ({ range, values }))
      : [{ range: "A1", values: [[null]] }],
  };
}
